// vm2_exec.c — the level-2 interpreter (展望③ 嵌套 VM).
//
// Executes the sealed L2 programs (vm2_prog.h, generated by vm2gen.c) that
// implement the L1 interpreter's semantic cores: vm_exec.c's OP_ARITH /
// OP_CMP / OP_CAST handlers call vm2_arith / vm2_cmp / vm2_cast here, so
// the arithmetic of the virtualized program is itself interpreted a second
// time — by a different machine (stack, not slots; disjoint opcode space;
// sealed programs; encrypted at rest, plaintext only in a heap working copy
// that is re-encrypted at process exit).
//
// Deliberate non-features: no calls, no memory access, no I/O — the L2 ISA
// cannot express anything but pure integer/FP computation over locals and a
// bounded stack, which keeps this interpreter small and auditable.
//
// Dependency-free C99 like vm_exec.c. Link next to vm_exec.c (its weak
// vm2_* hooks fall back to the native evaluators when this file is absent).

#include "vm2_exec.h"
#include "vm_crypt.h"
#include "vm2_prog.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// fp helpers (bit patterns <-> values) ---------------------------------------
static double b_f64(uint64_t b) { double d; uint64_t v = b; memcpy(&d, &v, 8); return d; }
static uint64_t f_b64(double d) { uint64_t b; memcpy(&b, &d, 8); return b; }
static float  b_f32(uint64_t b) { float f; uint32_t v = (uint32_t)b; memcpy(&f, &v, 4); return f; }
static uint64_t f_b32(float f)  { uint32_t v; memcpy(&v, &f, 4); return (uint64_t)v; }

// ---------------------------------------------------------------------------
// the stack machine
// ---------------------------------------------------------------------------
#define STK_MAX 64

static uint64_t vm2_run(const uint8_t *code, size_t size, uint64_t L[VM2_MAX_LOCALS]) {
    uint64_t st[STK_MAX];
    int sp = 0;                 // next free slot
    size_t pc = 0;
    uint32_t steps = 0;

#define PUSH(v) do { if (sp >= STK_MAX) return 0; st[sp++] = (v); } while (0)
#define POP()    (sp > 0 ? st[--sp] : 0)
#define NEED(n)  (pc + (n) <= size)
#define RD32()   (NEED(4) ? (uint32_t)((uint32_t)code[pc] | ((uint32_t)code[pc+1] << 8) | \
                                      ((uint32_t)code[pc+2] << 16) | ((uint32_t)code[pc+3] << 24)) \
                          : 0)
#define ADV(n)   (pc += (n))

    for (;;) {
        if (++steps > VM2_MAX_STEPS) return 0;
        if (!NEED(1)) return 0;
        uint8_t op = code[pc]; ADV(1);
        switch (op) {
        case VM2_PUSH_IMM: {
            if (!NEED(8)) return 0;
            uint64_t v = 0;
            for (int i = 7; i >= 0; i--) v = (v << 8) | code[pc + i];
            ADV(8); PUSH(v);
            break;
        }
        case VM2_PUSH_L: {
            if (!NEED(1)) return 0;
            uint8_t l = code[pc]; ADV(1);
            if (l >= VM2_MAX_LOCALS) return 0;
            PUSH(L[l]);
            break;
        }
        case VM2_STORE_L: {
            if (!NEED(1)) return 0;
            uint8_t l = code[pc]; ADV(1);
            if (l >= VM2_MAX_LOCALS) return 0;
            L[l] = POP();
            break;
        }
        case VM2_DROP: (void)POP(); break;
        case VM2_DUP:  { uint64_t v = POP(); PUSH(v); PUSH(v); break; }

        case VM2_ADD: case VM2_SUB: case VM2_MUL:
        case VM2_UDIV: case VM2_SDIV: case VM2_UREM: case VM2_SREM:
        case VM2_SHL: case VM2_LSHR: case VM2_SAR:
        case VM2_AND: case VM2_OR: case VM2_XOR: {
            uint64_t a, b, r = 0;
            b = POP(); a = POP();
            switch (op) {
            case VM2_ADD:  r = a + b; break;
            case VM2_SUB:  r = a - b; break;
            case VM2_MUL:  r = a * b; break;
            case VM2_UDIV: r = b ? a / b : 0; break;
            case VM2_SDIV: // INT64_MIN / -1 overflow mirrors arith_eval's guard
                if (!b) r = 0;
                else if (a == 0x8000000000000000ull && b == ~0ull) r = a;
                else r = (uint64_t)((int64_t)a / (int64_t)b);
                break;
            case VM2_UREM: r = b ? a % b : 0; break;
            case VM2_SREM:
                if (!b) r = 0;
                else if (a == 0x8000000000000000ull && b == ~0ull) r = 0;
                else r = (uint64_t)((int64_t)a % (int64_t)b);
                break;
            case VM2_SHL:  r = a << (b & 63); break;
            case VM2_LSHR: r = a >> (b & 63); break;
            case VM2_SAR:  r = (uint64_t)((int64_t)a >> (b & 63)); break;
            case VM2_AND:  r = a & b; break;
            case VM2_OR:   r = a | b; break;
            case VM2_XOR:  r = a ^ b; break;
            }
            PUSH(r);
            break;
        }

        case VM2_FADD64: case VM2_FSUB64: case VM2_FMUL64:
        case VM2_FDIV64: case VM2_FREM64: {
            uint64_t a, b;
            b = POP(); a = POP();
            double x = b_f64(a), y = b_f64(b), r = 0;
            switch (op) {
            case VM2_FADD64: r = x + y; break;
            case VM2_FSUB64: r = x - y; break;
            case VM2_FMUL64: r = x * y; break;
            case VM2_FDIV64: r = x / y; break;
            case VM2_FREM64: r = fmod(x, y); break;
            }
            PUSH(f_b64(r));
            break;
        }
        case VM2_FADD32: case VM2_FSUB32: case VM2_FMUL32:
        case VM2_FDIV32: case VM2_FREM32: {
            uint64_t a, b;
            b = POP(); a = POP();
            float x = b_f32(a), y = b_f32(b), r = 0;
            switch (op) {
            case VM2_FADD32: r = x + y; break;
            case VM2_FSUB32: r = x - y; break;
            case VM2_FMUL32: r = x * y; break;
            case VM2_FDIV32: r = x / y; break;
            case VM2_FREM32: r = fmodf(x, y); break;
            }
            PUSH(f_b32(r));
            break;
        }

        case VM2_EQ: case VM2_NE:
        case VM2_LTU: case VM2_LEU: case VM2_GTU: case VM2_GEU:
        case VM2_LTS: case VM2_LES: case VM2_GTS: case VM2_GES: {
            uint64_t a, b;
            b = POP(); a = POP();
            int64_t sa = (int64_t)a, sb = (int64_t)b;
            int r = 0;
            switch (op) {
            case VM2_EQ:  r = a == b; break;
            case VM2_NE:  r = a != b; break;
            case VM2_LTU: r = a <  b; break;
            case VM2_LEU: r = a <= b; break;
            case VM2_GTU: r = a >  b; break;
            case VM2_GEU: r = a >= b; break;
            case VM2_LTS: r = sa <  sb; break;
            case VM2_LES: r = sa <= sb; break;
            case VM2_GTS: r = sa >  sb; break;
            case VM2_GES: r = sa >= sb; break;
            }
            PUSH(r ? 1ull : 0ull);
            break;
        }

        case VM2_FEQ64: case VM2_FNE64: case VM2_FLT64:
        case VM2_FLE64: case VM2_FGT64: case VM2_FGE64: case VM2_ISNAN64: {
            if (op == VM2_ISNAN64) {
                double x = b_f64(POP());
                PUSH(x != x ? 1ull : 0ull);
                break;
            }
            uint64_t a, b;
            b = POP(); a = POP();
            double x = b_f64(a), y = b_f64(b);
            int r = 0;
            switch (op) {
            case VM2_FEQ64: r = x == y; break;
            case VM2_FNE64: r = x != y; break;
            case VM2_FLT64: r = x <  y; break;
            case VM2_FLE64: r = x <= y; break;
            case VM2_FGT64: r = x >  y; break;
            case VM2_FGE64: r = x >= y; break;
            }
            PUSH(r ? 1ull : 0ull);
            break;
        }
        case VM2_FEQ32: case VM2_FNE32: case VM2_FLT32:
        case VM2_FLE32: case VM2_FGT32: case VM2_FGE32: case VM2_ISNAN32: {
            if (op == VM2_ISNAN32) {
                float x = b_f32(POP());
                PUSH(x != x ? 1ull : 0ull);
                break;
            }
            uint64_t a, b;
            b = POP(); a = POP();
            float x = b_f32(a), y = b_f32(b);
            int r = 0;
            switch (op) {
            case VM2_FEQ32: r = x == y; break;
            case VM2_FNE32: r = x != y; break;
            case VM2_FLT32: r = x <  y; break;
            case VM2_FLE32: r = x <= y; break;
            case VM2_FGT32: r = x >  y; break;
            case VM2_FGE32: r = x >= y; break;
            }
            PUSH(r ? 1ull : 0ull);
            break;
        }

        case VM2_FPTOUI64: { uint64_t v = POP(); PUSH((uint64_t)b_f64(v)); break; }
        case VM2_FPTOSI64: { uint64_t v = POP(); PUSH((uint64_t)(int64_t)b_f64(v)); break; }
        case VM2_UITOFP64: { uint64_t v = POP(); PUSH(f_b64((double)v)); break; }
        case VM2_SITOFP64: { uint64_t v = POP(); PUSH(f_b64((double)(int64_t)v)); break; }
        case VM2_FPTOUI32: { uint64_t v = POP(); PUSH((uint64_t)b_f32(v)); break; }
        case VM2_FPTOSI32: { uint64_t v = POP(); PUSH((uint64_t)(int64_t)b_f32(v)); break; }
        case VM2_UITOFP32: { uint64_t v = POP(); PUSH(f_b32((float)v)); break; }
        case VM2_SITOFP32: { uint64_t v = POP(); PUSH(f_b32((float)(int64_t)v)); break; }
        case VM2_FPTRUNC:  { uint64_t v = POP(); PUSH(f_b32(b_f64(v))); break; }
        case VM2_FPEXT:    { uint64_t v = POP(); PUSH(f_b64((double)b_f32(v))); break; }

        case VM2_JMP: case VM2_JMPF: case VM2_JMPT: {
            if (!NEED(4)) return 0;
            uint32_t rel = RD32(); ADV(4);
            int64_t t = (int64_t)(int32_t)rel;
            int take = 1;
            if (op != VM2_JMP) take = POP() != 0;
            if (take) {
                if ((int64_t)pc + t < 0 || (size_t)((int64_t)pc + t) > size)
                    return 0;
                pc = (size_t)((int64_t)pc + t);
            }
            break;
        }
        case VM2_RET:
            return POP();

        default:
            return 0;      // unknown L2 opcode
        }
    }
#undef PUSH
#undef POP
#undef NEED
#undef RD32
#undef ADV
}

// ---------------------------------------------------------------------------
// sealed-program lifecycle: decrypt once per process; re-encrypt + free at
// exit. Lazy-init race is benign (both threads produce identical plaintext;
// one copy leaks). If an analyst dumps memory DURING execution they see the
// working copies; after exit, everything is ciphertext again.
// ---------------------------------------------------------------------------
static uint8_t *WP_arith, *WP_cmp, *WP_cast;
static volatile int WP_inited;

static uint8_t *vm2_unseal(const uint8_t *sealed, size_t n, const uint8_t key[16]) {
    uint8_t *w = (uint8_t *)malloc(n);
    if (!w) return NULL;
    memcpy(w, sealed, n);
    vm_keystream(w, n, key);
    return w;
}

static void vm2_fini(void) {
    if (WP_arith) {
        vm_keystream(WP_arith, VM2_PROG_ARITH_LEN, VM2_PROG_ARITH_KEY);
        free(WP_arith); WP_arith = NULL;
    }
    if (WP_cmp) {
        vm_keystream(WP_cmp, VM2_PROG_CMP_LEN, VM2_PROG_CMP_KEY);
        free(WP_cmp); WP_cmp = NULL;
    }
    if (WP_cast) {
        vm_keystream(WP_cast, VM2_PROG_CAST_LEN, VM2_PROG_CAST_KEY);
        free(WP_cast); WP_cast = NULL;
    }
    WP_inited = 0;
}

static int vm2_init(void) {
    if (WP_inited) return 1;
    WP_arith = vm2_unseal(VM2_PROG_ARITH_SEALED, VM2_PROG_ARITH_LEN,
                          VM2_PROG_ARITH_KEY);
    WP_cmp = vm2_unseal(VM2_PROG_CMP_SEALED, VM2_PROG_CMP_LEN,
                        VM2_PROG_CMP_KEY);
    WP_cast = vm2_unseal(VM2_PROG_CAST_SEALED, VM2_PROG_CAST_LEN,
                         VM2_PROG_CAST_KEY);
    if (!WP_arith || !WP_cmp || !WP_cast) return 0;
    atexit(vm2_fini);
    WP_inited = 1;
    return 1;
}

// ---------------------------------------------------------------------------
// public entries (strong definitions overriding vm_exec.c's weak fallbacks)
// ---------------------------------------------------------------------------
uint64_t vm2_arith(uint8_t sub, uint8_t tk, uint8_t bits, uint64_t a, uint64_t b) {
    if (!vm2_init()) return 0;
    uint64_t L[VM2_MAX_LOCALS] = {0};
    L[0] = sub; L[1] = tk; L[2] = bits; L[3] = a; L[4] = b;
    return vm2_run(WP_arith, VM2_PROG_ARITH_LEN, L);
}

int vm2_cmp(uint8_t pred, uint64_t a, uint64_t b, uint8_t obits) {
    if (!vm2_init()) return 0;
    uint64_t L[VM2_MAX_LOCALS] = {0};
    L[0] = pred; L[1] = a; L[2] = b; L[3] = obits;
    return (int)(vm2_run(WP_cmp, VM2_PROG_CMP_LEN, L) & 1u);
}

uint64_t vm2_cast(uint8_t cop, uint8_t sbits, uint8_t dbits, uint64_t v) {
    if (!vm2_init()) return 0;
    uint64_t L[VM2_MAX_LOCALS] = {0};
    L[0] = cop; L[1] = sbits; L[2] = dbits; L[3] = v;
    return vm2_run(WP_cast, VM2_PROG_CAST_LEN, L);
}
